text:
{
  "headline": "FDA's records trace our supply to a plant classified OAI 23 days before the shortage posting",
  "headline_cites": ["D8"],
  "sentences": [
    {
      "text": "FDA first posted the carboplatin shortage on 2023-04-28 and it remains current as of 2026-10-21.",
      "cites": ["E32", "D12"]
    },
    {
      "text": "The Accord Healthcare product on the shortage list uses carboplatin manufactured by Intas Pharmaceuticals Limited, a registered plant on the label.",
      "cites": ["E21", "E22"]
    },
    {
      "text": "FDA inspection 1191818 at Intas ended 2022-12-02 and was classified OAI, with the classification letter dated 2023-04-05.",
      "cites": ["E17"]
    },
    {
      "text": "That OAI classification letter came 23 days before FDA posted the shortage on 2023-04-28.",
      "cites": ["D8"]
    },
    {
      "text": "FDA subsequently issued an import alert for Intas on 2023-06-01 and a warning letter on 2023-07-28.",
      "cites": ["E19", "E18"]
    },
    {
      "text": "An alternate manufacturer, Apotex Corp., is approved for same-product substitution and its plant Teyro Labs Private Limited received a VAI classification on 2025-11-12.",
      "cites": ["E11", "E10", "E33"]
    },
    {
      "text": "The top-ranked operational option is to transfer 26 units from Corvale East to Corvale Lakeside, which would give Lakeside 14 days on hand while East retains two weeks.",
      "cites": ["D9"]
    }
  ]
}
